export interface OrderPort { place(order: Order): Promise<Receipt> }   // domain-owned

export class LegacyOrderAdapter implements OrderPort {
  constructor(private readonly client: HttpClient) {}
  async place(order: Order): Promise<Receipt> {
    const body: LegacyOrderDto = toLegacyDto(order);        // translate out
    const raw: unknown = await this.client.post("/orders", body);
    return toReceipt(LegacyReceipt.parse(raw));             // parse -> local type
  }
}
